Here is the root cause:
The bug is caused by the potential dereference of uninitialized pointers `symtab` and `sym_names` in the `encl_get_entry` function. If the enclave ELF file does not contain a symbol table, these pointers may remain uninitialized, leading to undefined behavior when accessed. The compiler warnings indicate that the code could attempt to use these pointers without proper initialization, which can result in crashes or incorrect program behavior.

Here is the patch:
  */
 uint64_t encl_get_entry(struct encl *encl, const char *symbol)
 {
+	Elf64_Sym *symtab = NULL;
+	char *sym_names = NULL;
 	Elf64_Shdr *sections;
-	Elf64_Sym *symtab;
 	Elf64_Ehdr *ehdr;
-	char *sym_names;
-	int num_sym;
+	int num_sym = 0;
 	int i;

 	ehdr = encl->bin;
 	sections = encl->bin + ehdr->e_shoff;

 	for (i = 0; i < ehdr->e_shnum; i++) {
 		if (sections[i].sh_type == SHT_SYMTAB) {
 			symtab = (Elf64_Sym *)((char *)encl->bin + sections[i].sh_offset);
 			num_sym = sections[i].sh_size / sections[i].sh_entsize;
 			break;
 		}
 	}

 	for (i = 0; i < ehdr->e_shnum; i++) {
 		if (sections[i].sh_type == SHT_STRTAB) {
 			sym_names = (char *)encl->bin + sections[i].sh_offset;
 			break;
 		}
 	}

+	if (!symtab || !sym_names)
+		return 0;
+
 	for (i = 0; i < num_sym; i++) {
 		Elf64_Sym *sym = &symtab[i];

 		if (!strcmp(symbol, sym_names + sym->st_name))
 			return (uint64_t)sym->st_value;
 	}

 	return 0;
 }



